<template>
 <view class="screen shop-ui" :class="{'has-tabs':mainTabs,'has-action':bottomAction,'weixin':isWechat,'catalog-screen':screen==='category'}">
  <view class="navbar" :style="{paddingTop:statusBar+'px'}"><view class="nav-content"><view v-if="screen==='index'" class="brand"><image v-if="media('brand.logo')" :src="media('brand.logo')" mode="aspectFit" style="width:28px;height:28px;vertical-align:middle;margin-right:6px"/>{{rules.shopName||'赫洛嘉'}}</view><view v-else-if="!mainTabs" class="back" @click="back"><UiIcon name="back"/></view><view v-if="screen==='index'" class="search-mini" @click="go('search')"><UiIcon name="search" :size="16"/><text>搜索商品</text></view><text v-else class="nav-title">{{screen==='category'?(rules.shopName||'赫洛嘉'):(screen==='address-edit'&&query.id?'编辑地址':(titles[screen]||'美容商城'))}}</text><view class="nav-right" @click="screen==='category'?go('search'):authGo('notices')"><UiIcon :name="screen==='category'?'search':'message'" :size="21"/></view></view></view>
  <view v-if="error" class="error-card"><UiIcon name="cloud" :size="46"/><text>{{error}}</text><button v-if="screen==='checkout'&amp;&amp;pendingSubmission" class="ui-button primary" :disabled="busy" @click="submitOrder">核对上次提交</button><button class="ui-button primary" @click="refresh()">重新加载</button><button class="ui-button outline" @click="go('orders')" v-if="query.id&amp;&amp;screen!=='product'">查看订单</button><button class="ui-button outline" @click="home('me')">返回我的</button></view>
  <view v-else-if="loading&&!initialized" class="skeleton"><view class="skeleton-hero"/><view class="skeleton-row"/><view class="skeleton-hero"/></view>
  <template v-else><view v-if="commissionDebt(distribution)>0" class="notice">退款佣金待抵扣 ¥{{money(commissionDebt(distribution))}}，后续佣金优先抵扣后再提现。</view>
   <view v-if="selfPurchaseProfile?.enabled&&channel==='C'&&['index','category','search','product','cart'].includes(screen)" class="notice" @click="go('partner')">您已开通{{selfPurchaseProfile.name}}专属拿货权益，进入专属拿货页查看价格 ›</view>
   <view v-if="screen==='index'" class="archive-entry" @click="authGo('customer-profile')"><view class="archive-entry-copy"><text class="archive-entry-title">{{member?.contact_phone?'查看我的商城档案':'建立我的商城档案'}}</text><text class="archive-entry-hint">{{member?.contact_phone?'查看个人购物、分销与企业资格':'填写称呼和电话，了解自己的 C 端与 B 端权益'}}</text></view><text class="archive-entry-arrow">›</text></view>
   <HomeModules v-if="screen==='index'" :categories="categories" :products="products" :refresh-tick="refreshTick"/>
   <template v-if="screen==='category'">
    <HorizontalScroll class="catalog-groups"><view class="catalog-group-list"><view v-for="(g,idx) in majorGroups" :key="g.name" class="catalog-group" :class="{active:majorCategory===idx}" @click="selectMajorGroup(idx)"><text>{{g.name}}</text></view></view></HorizontalScroll>
    <view class="catalog-layout" :style="{height:catalogHeight}">
     <VerticalScroll class="catalog-side" :viewport-style="{width:'78px',flexShrink:0,background:'#f3f8fb'}" :height="catalogHeight"><view class="series-nav" :class="{selected:selectedSeries===null}" @click="selectCatalogSeries(null)"><UiIcon name="grid" :size="28"/><text>{{catalogHasSeries?'全部系列':'全部分类'}}</text></view><view v-for="(s,i) in seriesChoices" :key="s" class="series-nav" :class="{selected:selectedSeries===s}" @click="selectCatalogSeries(s)"><image v-if="products.find(p=>p.category===s)?.image" :src="asset(products.find(p=>p.category===s).image,160)" mode="aspectFill" class="catalog-category-image"/><UiIcon v-else name="grid" :size="30"/><text>{{s||'其他商品'}}</text></view></VerticalScroll>
     <VerticalScroll class="category-main catalog-scroll" :viewport-style="{flex:1,width:0,minWidth:0,padding:0}" :height="catalogHeight" :scroll-top="catalogScrollTop" @scroll="catalogScrollTop=$event.detail.scrollTop" @scrolltolower="visibleCount+=20">
      <view class="catalog-content"><view class="catalog-pickers"><picker :range="['全部系列',...seriesNames]" @change="catalogSeries=['全部系列',...seriesNames][Number($event.detail.value)];visibleCount=20"><text>{{catalogSeries}} ▾</text></picker><picker :range="['全部',...brands]" @change="brand=['全部',...brands][Number($event.detail.value)];visibleCount=20"><text>{{brand==='全部'?'全部品牌':brand}} ▾</text></picker></view><view v-if="catalogBanner" class="catalog-banner"><image :src="catalogBanner" mode="aspectFill"/><view class="catalog-banner-copy"><text>{{selectedSeries===null?majorGroups[majorCategory]?.name||'产品系列':selectedSeries||'每日护理'}}</text></view></view>
       <view v-if="category!=='全部'" class="catalog-filter" @click="category='全部'">{{category}} · 查看全部 ›</view>
       <view v-for="section in seriesSections" :key="section.name" class="catalog-section"><view class="catalog-series-title"><text>{{section.name||'每日护理'}}</text></view><view class="catalog-products"><view v-for="p in section.products" :key="p.id" class="product-card" @click="openProduct(p)"><view class="catalog-product-image"><image :lazy-load="true" :src="asset(p.image,320)" :class="productPhotoClass(p.image)" mode="aspectFit"/></view><text class="product-name">{{p.name}}</text><text class="catalog-spec">{{p.spec}}</text><text class="catalog-price"><text v-if="p.priceLabel" class="small">{{p.priceLabel}} </text>¥{{money(unitPrice(p))}}</text><text v-if="campaignOffer(p)" class="catalog-spec">活动价 ¥{{money(campaignOffer(p).price)}}{{campaignOffer(p).conditional?'（限符合条件的顾客）':''}}</text><text v-if="soldCountText(p.soldCount)" class="sold-count">{{soldCountText(p.soldCount)}}</text></view></view></view>
       <view v-if="!seriesSections.length" class="category-empty">当前分组暂无商品</view>
      </view>
     </VerticalScroll>
    </view>
   </template>
   <template v-if="screen==='search'"><view class="search-bar"><UiIcon name="search" :size="18"/><input v-model="keyword" placeholder="搜索商品、功效或品牌" confirm-type="search"/><text @click="keyword=''">清空</text></view><view class="filter-bar"><text :class="{on:sort==='default'}" @click="sort='default'">综合</text><text :class="{on:sort==='price'}" @click="sort=sort==='price'?'priceDesc':'price'">价格 ↕</text><text :class="{on:sort==='sales'}" @click="sort='sales'">销量</text><text @click="filterOpen=true">筛选 ▽</text></view><view class="product-grid two padded"><view v-for="p in filteredProducts.slice(0,visibleCount)" :key="p.id" class="product-card" @click="openProduct(p)"><image :lazy-load="true" :src="asset(p.image)" mode="aspectFit"/><text class="product-name">{{p.name}} {{p.spec}}</text><text v-if="soldCountText(p.soldCount)" class="sold-count">{{soldCountText(p.soldCount)}}</text><view class="between"><text class="price">¥{{money(unitPrice(p))}}</text></view></view></view><button v-if="filteredProducts.length>visibleCount" class="ui-button outline" @click="visibleCount+=20">查看更多商品（{{visibleCount}} / {{filteredProducts.length}}）</button><view v-if="!filteredProducts.length" class="empty"><UiIcon name="search" :size="60"/><text>没有找到相关商品</text><text class="muted small">换个关键词，发现更多好物</text></view></template>
   <template v-if="screen==='product'&&selectedProduct"><swiper class="detail-gallery" indicator-dots :autoplay="false"><swiper-item v-for="img in gallery" :key="img"><image :lazy-load="true" :src="asset(img,960)" :class="productPhotoClass(img)" mode="aspectFit"/></swiper-item></swiper><view class="detail-info"><text class="product-title">{{selectedProduct.name}} {{selectedProduct.spec}}</text><text class="muted small block">{{selectedProduct.brand||'赫洛嘉'}} · {{selectedProduct.series||'护肤系列'}}</text><view class="between"><text class="price large"><text v-if="selectedProduct.priceLabel" class="small">{{selectedProduct.priceLabel}} </text>¥{{money(unitPrice(selectedProduct))}}</text><text class="muted small">{{soldCountText(selectedProduct.soldCount)?soldCountText(selectedProduct.soldCount)+' · ':''}}库存 {{selectedProduct.stock}} 件</text></view><text v-if="campaignOffer(selectedProduct)" class="notice block">活动价 ¥{{money(campaignOffer(selectedProduct).price)}}，结算时自动按活动价计算{{campaignOffer(selectedProduct).conditional?'（限符合活动条件的顾客，以结算页为准）':'，以结算页为准'}}</text><view class="product-share-actions"><button v-if="isWechat" class="ui-button outline" open-type="share" data-share-kind="product" :data-product-id="selectedProduct.id" :data-share-title="selectedProduct.name" :data-channel="channel">分享给微信好友</button><button class="ui-button outline" :disabled="copying" @click="shareProduct(selectedProduct)">复制商品浏览链接</button></view><text class="small muted block">{{linkNote()}}</text><view v-if="channel==='B'" class="membership">{{purchasePrice(selectedProduct).basis}} · {{selectedProduct.pack}} 件/箱<text v-for="t in selectedProduct.tiers||[]" :key="t.quantity" class="small block">满 {{t.quantity}} 件，¥{{money(t.price)}} / 件</text></view><view v-if="channel==='C'&&selectedProduct.purchaseMode!=='partner'&&rules.couponDiscount>0" class="line" @click="go('coupons')"><text class="muted">满减优惠</text><text class="coupon-tag">满{{rules.couponThreshold/100}}减{{rules.couponDiscount/100}}</text><text class="more">查看 ›</text></view><view class="service-row"><text>✓ 品质甄选</text><text>✓ 售后服务</text><text>✓ 正品保障</text></view><view class="line" @click="showSku('cart')"><text class="muted">规格</text><text>{{selectedProduct.spec||'默认规格'}}</text><text class="more">›</text></view></view><view class="detail-description"><view v-if="selectedProduct.video_url" class="product-video-block"><view class="section-title compact">商品视频</view><video v-if="!productVideoFailed" :key="selectedProduct.id+'-'+productVideoRetry" class="product-video" :src="asset(selectedProduct.video_url)" :poster="asset(selectedProduct.image)" :autoplay="false" controls object-fit="contain" @error="productVideoFailed=true"/><view v-else class="video-error"><text>视频暂时无法播放，请检查网络后重试</text><button class="ui-button outline mini" @click="productVideoRetry++;productVideoFailed=false">重新加载视频</button></view></view><view class="section-title compact">商品介绍</view><text class="description">{{String(selectedProduct.detail||'').trim()}}</text><image :lazy-load="true" v-for="img in gallery" :key="img" :src="asset(img,960)" mode="widthFix"/></view><view class="bottom-bar product-bottom"><view @click="go('support')"><UiIcon name="message" :size="21"/><text>客服</text></view><view class="product-cart-link" @click="go('cart',{channel})"><UiIcon name="cart" :size="21"/><text>购物车</text><text v-if="cartQuantity" class="cart-count">{{cartQuantity>99?'99+':cartQuantity}}</text></view><button class="ui-button primary soft" @click="showSku('cart')">加入购物车</button><button class="ui-button primary" @click="showSku('buy')">立即购买</button></view></template>
   <template v-if="screen==='cart'"><view v-if="cartMergeError" class="white-card"><text class="bold block">游客商品待确认</text><text class="small block">{{cartMergeError}}</text><text v-for="(i,index) in pendingGuestItems" :key="index" class="small block">{{i.name||'商品'}} × {{i.quantity}}</text><text class="muted small block">请核对当前购物车。确认加入会在现有数量上增加；已包含则不会再次增加。</text><button class="ui-button outline" :disabled="busy" @click="reviewGuestCart('retry')">确认加入以上商品</button><button class="ui-button outline" :disabled="busy" @click="reviewGuestCart('accept')">以上商品已在购物车中</button><button class="ui-button outline" :disabled="busy" @click="reviewGuestCart('discard')">放弃以上待合并记录</button></view><view v-if="channel==='B'" class="notice">企业采购 · 按整箱数量下单 · 满 ¥{{money(rules.minimumWholesale)}} 起订</view><view v-if="!cartItems.length" class="empty"><image :lazy-load="true" v-if="media('empty.cart')" :src="media('empty.cart')" mode="aspectFit" class="empty-image"/><UiIcon v-else name="bag" :size="76"/><text class="empty-title">购物车还是空的</text><text class="muted small">去挑选心仪的好物吧</text><button class="ui-button primary" @click="channel==='B'?go('business'):home()">去逛逛</button></view><template v-else><view class="cart-top"><text>购物车（{{cartQuantity}} 件）</text><text @click="cartEditing=!cartEditing">{{cartEditing?'完成':'编辑'}}</text></view><view v-for="i in cartItems" :key="i.id" class="cart-item"><view class="check" :class="{checked:i.checked,disabled:!!i.invalid}" @click="toggleItem(i)">{{i.checked?'✓':''}}</view><image :lazy-load="true" :src="asset(i.image)" mode="aspectFill" @click="openProduct(i)"/><view class="cart-info"><text class="bold">{{i.name}} {{i.spec}}</text><text v-if="i.spec" class="spec">规格：{{i.spec}}</text><text v-if="campaignOffer(i)" class="spec">活动价 ¥{{money(campaignOffer(i).price)}}{{campaignOffer(i).conditional?'（限符合活动条件的顾客）':''}}，结算时自动按活动价计算</text><view class="between"><text class="price"><text v-if="i.priceLabel" class="small">{{i.priceLabel}} </text>¥{{money(unitPrice(i))}}</text><view class="stepper"><button class="ui-button" @click="changeQty(i,-1)">−</button><text>{{i.quantity}}</text><button class="ui-button" @click="changeQty(i,1)">＋</button></view></view><text v-if="cartEditing" class="delete" @click="removeItem(i)">移除商品</text><text v-if="i.invalid" class="delete">{{i.invalid}}，请调整数量或移除</text><text v-if="i.invalid&amp;&amp;!cartEditing" class="delete" @click="removeItem(i)">移除商品</text></view></view><view class="coupon-note" v-if="channel==='C'&&rules.couponDiscount>0&&!checkedItems.some(i=>i.purchaseMode==='partner')"><text>优惠提醒</text><text class="small block">{{cartSubtotal>=rules.couponThreshold?'结算时可享满减优惠':'满 '+rules.couponThreshold/100+' 元可享优惠'}}</text></view><view class="bottom-bar cart-bottom"><view class="all-select" @click="toggleAll"><view class="check" :class="{checked:allSelected}">{{allSelected?'✓':''}}</view><text>全选</text></view><view class="total">预估合计：<text class="price">¥{{money(cartPayable)}}</text></view><button class="ui-button primary" :disabled="!checkedItems.length" @click="checkoutCart">结算（{{checkedItems.reduce((total,item)=>total+item.quantity,0)}}）</button></view></template></template>
   <button v-if="screen==='category'&&visibleCount<seriesCatalogProducts.length" class="ui-button outline" @click="visibleCount+=20">查看更多商品</button><template v-if="screen==='member-center'"><view class="white-card line" @click="authGo('point-exchange')"><text>积分兑换</text><text class="more">用积分兑换商品 ›</text></view><view class="white-card line" @click="authGo('grades')"><text>充值消费优惠</text><text class="more">查看我的折扣 ›</text></view><view class="white-card line" @click="authGo('notices')"><text>站内消息</text><text class="more">查看订单进度和客服回复 ›</text></view><view class="white-card line" @click="authGo('reviews')"><text>我的评价</text><text class="more">评价已收商品、补充使用感受 ›</text></view><view class="white-card line" @click="authGo('invoices')"><text>发票中心</text><text class="more">申请、查看和下载票据 ›</text></view><view class="white-card line" @click="authGo('points')"><text>我的积分</text><text class="more">查看积分和使用规则 ›</text></view><view class="white-card line" @click="authGo('wallet')"><text>余额钱包</text><text class="more">查看余额和明细 ›</text></view></template><PartnerCenter v-if="screen==='partner'&&member" :member="member" :query="query" :refresh-tick="refreshTick"/><template v-if="screen==='me'"><StaffModeSwitch :staff="staffStatus"/><view class="profile-card" @click="go(member?'settings':'login')"><view class="avatar"><image v-if="member?.avatar" :src="asset(member.avatar)" mode="aspectFill" style="width:100%;height:100%;border-radius:50%"/><UiIcon v-else name="user" :size="35"/></view><view><text class="profile-name">{{member?.nickname||'欢迎来到美容商城'}}</text><text v-if="member" class="small muted block">会员编号 {{member.id}}</text><text class="small muted block">{{identitySummary}}</text></view><text class="more">›</text></view><ProfileComplete v-if="needsProfile" :key="'me-'+member.id" :member="member" @saved="profileSaved"/><view v-if="!staffStatus&&staffFailed" class="white-card line staff-entry" role="alert" @click="retryStaffStatus"><UiIcon name="bag"/><view class="staff-entry-copy"><text class="bold block">管理入口暂时没读取到</text><text class="small muted block">网络或服务暂时不稳定 · 点这里重试</text></view><text class="more">重试</text></view><view v-if="staffStatus" class="white-card line staff-entry" @click="openWorkbench()"><UiIcon name="bag"/><view class="staff-entry-copy"><text class="bold block">进入手机管理</text><text class="small muted block">{{staffStatus.name||'店铺员工'}}{{staffStatus.roleLabel?' · '+staffStatus.roleLabel:''}} · 查看并处理店铺事务</text></view><text class="more">›</text></view><view class="white-card line" @click="authGo('customer-profile')"><text class="bold">我的商城档案</text><text class="more">联系信息与会员权益 ›</text></view><view class="white-card line" @click="go('member-center')"><text class="bold">会员中心</text><text class="more">积分、充值优惠、消息与会员服务 ›</text></view><view class="white-card"><view class="section-title compact" @click="authGo('orders')"><text>我的订单</text><text class="more">全部订单 ›</text></view><view class="order-shortcuts"><view v-for="s in ['pending','paid','shipped','completed']" :key="s" @click="authGo('orders',{status:s})"><UiIcon :name="s==='pending'?'wallet':s==='paid'?'bag':s==='shipped'?'truck':'check'"/><text>{{labels[s]}}</text></view><view @click="authGo('after-sales')"><UiIcon name="refund"/><text>售后/退款</text></view></view></view><view class="benefit-row"><view @click="go('coupons')"><text>满减礼遇</text></view><view @click="authGo('notices')"><text>消息通知</text></view><view @click="authGo('reviews')"><text>我的评价</text></view></view><view v-if="member?.distributor_state==='approved'||partnerInfo?.assisting?.length" class="white-card line" @click="authGo('partner')"><text class="bold">{{partnerEntry.title}}</text><text class="more">{{partnerEntry.hint}} ›</text></view><view class="white-card identity-card"><view class="identity-entry" @click="authGo('distribution')"><view class="identity-icon warm"><UiIcon name="share" :size="25"/></view><view><text class="bold">{{distributionEntry.title}}</text><text class="small muted block">{{distributionEntry.hint}}</text></view><text class="more">›</text></view></view><view class="white-card"><view class="line" @click="authGo('invoices')"><text>发票中心</text><text class="more">申请与查看发票 ›</text></view><view class="line" @click="authGo('addresses')"><UiIcon name="pin"/><text>收货地址</text><text class="more">›</text></view><view class="line" @click="go('support')"><UiIcon name="message"/><text>帮助与客服</text><text class="more">›</text></view><view class="line" @click="go('settings')"><UiIcon name="settings"/><text>账户与设置</text><text class="more">›</text></view></view></template>
   <template v-if="screen==='login'"><view class="login-heading"><text class="product-title">{{isWechat?'微信一键登录':'登录与下单'}}</text><text class="muted small block">零售购物、分销拿货和推广，共用一个微信账号</text></view><image :lazy-load="true" class="login-hero" :src="media('login.hero')" mode="aspectFill"/><view class="login-form"><template v-if="isWechat"><view class="agreement"><view class="check" :class="{checked:agreed}" @click="agreed=!agreed">{{agreed?'✓':''}}</view><text @click="agreed=!agreed">我已阅读并同意</text><text class="green" @click="go('agreement')">《用户协议与隐私说明》</text></view><view v-if="!demoMode&&!agreementContent" class="notice" @click="go('agreement')">商家尚未配置正式协议，请先查看说明并联系商家确认。</view><template v-if="bindExisting"><text class="small muted block">首次验证原账号并绑定微信，保留原订单、企业认证和分销资料。以后直接微信登录。</text><input class="field" v-model="username" maxlength="40" placeholder="原商城账号"/><input class="field" v-model="password" password maxlength="64" placeholder="原商城密码"/><view class="appeal-link" @click="go('account-appeal')"><text>忘记原账号密码？</text><text class="green">申请人工找回 ›</text></view></template><button class="ui-button primary" :loading="busy" :disabled="busy" @click="wechatLogin">{{bindExisting?'验证原账号并绑定微信':'微信一键登录'}}</button><view class="login-divider" @click="bindExisting=!bindExisting;password=''">{{bindExisting?'我是新用户，返回微信登录':'已有商城账号？首次绑定微信'}}</view></template><view v-else class="white-card h5-stop"><text class="bold">{{h5Guide().title}}</text><text class="small muted block">{{h5Guide().reason}}</text><text class="small muted block">{{h5Guide().how}}</text><text v-if="h5Guide().note" class="small muted block">{{h5Guide().note}}</text><button class="ui-button outline" :disabled="copying" @click="copy(h5Guide().name)">复制小程序名称</button></view><text class="skip" @click="home()">暂不登录，先逛逛</text></view></template>
   <template v-if="screen==='checkout'"><view v-if="pendingSubmission" class="notice">上次提交结果待确认。请先核对原订单；本页后续修改不会应用到原订单。<text class="block">原收货人：{{pendingSubmission.address.name}} {{pendingSubmission.address.phone}}，{{pendingSubmission.address.address}}；原金额 ¥{{money(pendingSubmission.expectedAmount)}}</text><button class="ui-button outline" :disabled="busy" @click="submitOrder">核对上次提交</button></view><view v-if="partnerPurchase" class="notice">专属拿货 · {{quote.rules?.partner?.name||'资格核验中'}} · {{quote.rules?.partner?.rate/1000||''}}折；拿货订单用微信付款，也可以用门店余额抵扣；不能使用优惠券、积分、活动和小程序充值余额，也不送消费积分。</view><view v-if="checkoutItems.some(i=>i.previousPrice!=null)" class="notice">再次购买将按当前价格、库存和优惠重新结算。<view v-for="i in checkoutItems.filter(i=>i.previousPrice!=null)" :key="i.id">{{i.name}}：原单价 ¥{{money(i.previousPrice)}}，{{againPriceText(i)}}</view></view><view v-if="deliveryMethod==='pickup'" class="white-card"><input class="field" v-model="pickupName" placeholder="取货人姓名"/><input class="field" v-model="pickupPhone" placeholder="取货人手机号" maxlength="11"/></view><view v-else class="address-card" @click="go('addresses',{select:1})"><UiIcon name="pin"/><view v-if="address.name"><text class="bold">{{address.name}}　{{address.phone}}</text><text class="small muted block">{{address.address}}</text></view><text v-else>请选择收货地址</text><text class="more">›</text></view><view class="white-card"><view class="section-title compact">商品清单 <text class="more">共 {{checkoutItems.length}} 种</text></view><view v-for="i in checkoutItems" :key="i.id" class="checkout-item"><image :lazy-load="true" :src="asset(i.image)" mode="aspectFill"/><view><text class="bold">{{i.name}}</text><text v-if="i.invalid" class="delete block">{{i.invalid}}</text><button v-if="i.invalid" class="ui-button outline mini" @click="removeCheckout(i)">确认移除</button><text class="small muted block">{{i.spec}}</text><text class="price block">¥{{money(quote.items?.find(q=>q.id===i.id)?.unitPrice??unitPrice(i))}}</text></view><text class="more">× {{i.quantity}}</text></view></view><view class="white-card"><view class="line"><text>配送方式</text><picker v-if="deliveryChoices.length>1" :range="deliveryChoices" range-key="label" @change="deliveryMethod=deliveryChoices[Number($event.detail.value)].id;getQuote()"><text>{{deliveryChoices.find(x=>x.id===deliveryMethod)?.label}} ›</text></picker><text v-else>{{deliveryChoices[0]?.label||'配送方式加载中'}}</text></view><view v-if="deliveryMethod==='pickup'" class="line" :class="{'line-joined':selectedPickupPoint}"><text>取货门店</text><picker :range="deliveryOptions.points" range-key="name" @change="pickupPoint=deliveryOptions.points[Number($event.detail.value)].id;getQuote()"><text>{{deliveryOptions.points.find(x=>x.id===pickupPoint)?.name||'请选择门店'}} ›</text></picker></view><view v-if="deliveryMethod==='pickup'&&selectedPickupPoint" class="pickup-store"><text class="small muted block">{{selectedPickupPoint.address}}</text><text class="small muted block">{{pickupHoursText(selectedPickupPoint)}}</text></view><view v-if="channel==='C'&&!exchange&&!campaignId&&!partnerPurchase" class="line"><text>使用满减优惠</text><switch :checked="useCoupon" color="#73afcb" @change="useCoupon=$event.detail.value;getQuote()"/></view><view v-if="channel==='C'&&!exchange&&!campaignId&&!partnerPurchase" class="line"><text>选择优惠券</text><picker :range="couponOptions" range-key="label" @change="chooseCoupon"><text class="more">{{couponOptions.find(c=>c.id===couponId)?.label||'不使用优惠券'}} ›</text></picker></view><view v-if="channel==='C'&&!exchange&&!campaignId&&!partnerPurchase" class="line"><text>使用积分（可用{{pointsAccount.available}}分）</text><switch :checked="usePoints" color="#73afcb" @change="usePoints=$event.detail.value;getQuote()"/></view><view v-if="channel==='B'" class="line"><text>付款方式</text><button class="ui-button" :class="paymentMethod==='simulation'?'primary mini':'outline mini'" @click="choosePayment('simulation')">普通付款</button><button class="ui-button" :class="paymentMethod==='credit'?'primary mini':'outline mini'" @click="choosePayment('credit')">账期采购</button></view><view v-if="channel==='C'&&!partnerPurchase&&paymentMethod!=='credit'&&(onlineWalletAccount.available>0||useOnlineBalance)" class="line"><text>使用小程序余额（¥{{money(onlineWalletAccount.available)}}）</text><switch :checked="useOnlineBalance" color="#73afcb" @change="useOnlineBalance=$event.detail.value;if(useOnlineBalance){useBalance=false;useRebate=false}getQuote()"/></view><view v-if="quote.rules?.retailRecharge?.tier&&!partnerPurchase" class="line"><text>充值消费折扣</text><text>{{quote.rules.retailRecharge.rate/1000}}折（已计入商品价）</text></view><view v-if="paymentMethod!=='credit'&&rules.walletPaymentEnabled!==false&&walletAccount.available>0" class="line"><text>使用门店余额（可用¥{{money(walletAccount.available)}}）</text><switch :checked="useBalance" color="#73afcb" @change="useBalance=$event.detail.value;if(useBalance){useRebate=false;useOnlineBalance=false};getQuote()"/></view><view v-if="channel==='B'&&paymentMethod!=='credit'" class="line"><text>使用企业返利（可用¥{{money(Math.max(0,rebateAccount.available))}}）</text><switch :checked="useRebate" color="#73afcb" @change="useRebate=$event.detail.value;if(useRebate)useBalance=false;getQuote()"/></view><view v-if="quote.rebateUsed" class="line"><text>企业返利抵扣</text><text>¥{{money(quote.rebateUsed)}}</text></view><view v-for="g in quote.rules?.gifts||[]" :key="g.id" class="line"><text>赠品：{{g.name}} × {{g.quantity}}</text><text>¥0.00</text></view><view class="line"><text>商品金额</text><text class="more">¥{{money(quote.subtotal)}}</text></view><view v-if="offerDiscount(quote)" class="line"><text>优惠金额</text><text class="more price">−¥{{money(offerDiscount(quote))}}</text></view><view v-if="quote.pointsUsed" class="line"><text>{{quote.exchange?'积分兑换':'积分抵扣'}}（{{quote.pointsUsed}}分）</text><text class="more price">−¥{{money(quote.pointsDiscount)}}</text></view><view v-if="shippingText(quote.shippingFee,deliveryMethod)" class="line"><text>运费</text><text class="more">{{shippingText(quote.shippingFee,deliveryMethod)}}</text></view><view v-if="quote.walletUsed" class="line"><text>余额支付</text><text class="more">¥{{money(quote.walletUsed)}}</text></view><view v-if="quote.walletUsed||quote.rebateUsed||quote.pointsUsed" class="line"><text>还需付款</text><text class="more">¥{{money(quote.externalAmount)}}</text></view></view><text v-if="quoteLoading" class="quote-status">正在更新金额…</text><view v-if="quoteError" class="notice">{{quoteError}}</view><view class="bottom-bar"><text>实付款：<text class="price">¥{{money(quote.amount)}}</text></text><button class="ui-button primary" :loading="busy" :disabled="busy||(!pendingSubmission&&(quoteLoading||!!quoteError||!quote.items))" @click="submitOrder">{{pendingSubmission?'核对上次提交':'提交订单'}}</button></view></template>
   <template v-if="screen==='addresses'"><view v-for="a in addresses" :key="a.id" class="white-card address-option"><view @click="chooseAddress(a)"><text class="bold">{{a.name}}　{{a.phone}}</text><text v-if="a.is_default" class="tag">默认</text><text class="small muted block">{{a.address}}</text></view><view class="address-actions"><text class="green" @click="chooseAddress(a)">选择地址</text><text class="green" @click="go('address-edit',{id:a.id})">编辑</text><text class="muted" @click="deleteAddress(a)">删除</text></view></view><view v-if="!addresses.length" class="empty"><UiIcon name="pin" :size="52"/><text>还没有收货地址</text></view><view class="bottom-bar"><button class="ui-button outline full" @click="go('address-edit')">＋ 添加新地址</button></view></template>
   <template v-if="screen==='address-edit'"><view class="white-card form"><text class="form-label">收货人</text><input class="field" v-model="addressForm.name" placeholder="请输入收货人姓名"/><text class="form-label">手机号</text><input class="field" v-model="addressForm.phone" type="number" maxlength="11" placeholder="请输入手机号"/><text class="form-label">省、市、区县</text><!-- #ifdef MP-WEIXIN --><picker mode="region" :value="[addressForm.province,addressForm.city,addressForm.district]" @change="chooseRegion"><view class="field region-field">{{addressForm.province?[addressForm.province,addressForm.city,addressForm.district].join(' / '):'请选择省、市、区县'}} ›</view></picker><!-- #endif --><!-- #ifndef MP-WEIXIN --><input class="field" v-model="addressForm.province" placeholder="省或直辖市，如广东省" maxlength="40"/><input class="field" v-model="addressForm.city" placeholder="市，如广州市" maxlength="40"/><input class="field" v-model="addressForm.district" placeholder="区县，如天河区" maxlength="40"/><!-- #endif --><text class="form-label">街道与门牌号</text><textarea class="field textarea" v-model="addressForm.detail" placeholder="详细到街道、楼栋、门牌号" maxlength="200"/><text v-if="addressForm.id&&!addressForm.province" class="small muted">原完整地址：{{addressForm.address}}。修改时请补齐上方地区信息。</text><text v-if="false" class="form-label">所在地区与详细地址</text><textarea v-if="false" class="field textarea" v-model="addressForm.address" placeholder="省、市、区、街道及门牌号" maxlength="300"/><view class="line"><text>设为默认地址</text><switch :checked="addressForm.is_default" @change="addressForm.is_default=$event.detail.value" color="#73afcb"/></view></view><view class="bottom-bar"><button class="ui-button primary full" :loading="busy" @click="saveAddress">保存地址</button></view></template>
   <template v-if="screen==='cashier'"><BankPanel :refresh-tick="refreshTick" v-if="currentOrder?.channel==='B'&&!currentOrder?.credit_order&&!currentOrder?.wallet_amount&&!currentOrder?.rebate_amount&&member?.company_role!=='buyer'" :order-id="currentOrder.id" @ready="bankActive=$event" @updated="refresh(true)"/><view class="cashier"><view v-if="currentOrder?.rebate_amount" class="small muted">企业返利已占用 ¥{{money(currentOrder.rebate_amount)}}，还需付款 ¥{{money(currentOrder.external_amount)}}</view><view v-if="currentOrder?.wallet_amount" class="small muted">余额已占用 ¥{{money(currentOrder.wallet_amount)}}，还需付款 ¥{{money(currentOrder.external_amount)}}</view><text class="muted">订单金额</text><text class="price money-xl">¥{{money(currentOrder?.amount)}}</text><text class="small muted">订单号 {{currentOrder?.order_no}}</text><text class="small muted block">请在 {{date(currentOrder?.expires_at)}} 前付款，超时自动关闭。</text></view><view class="white-card"><view class="section-title compact">选择支付方式</view><view class="line"><UiIcon name="wallet"/><text>{{cashierPaymentText.label}}</text><view class="check checked more">✓</view></view><text class="small muted">{{cashierPaymentText.hint}}</text></view><view class="bottom-bar"><text v-if="currentOrder?.company_id&&member?.company_role==='buyer'">订单已提交，请由企业负责人或财务付款。</text><text v-else-if="currentOrder&&Number(currentOrder.amount)===0&&!parse(currentOrder.rules_json).exchange&&!demoMode">这笔订单优惠后为0元，无法付款，请取消订单后重新下单。</text><text v-else-if="bankActive">已选择对公转账，等待财务核验到账。</text><text v-else-if="(!wechatPayReady||!isWechat)&&(!demoMode||parse(currentOrder?.rules_json).simulationPaymentEnabled===false)&&!currentOrder?.credit_order&&currentOrder?.external_amount>0">{{wechatPayReady&&!isWechat?payOnPhoneText():'商家暂未开放在线付款，请选择可用付款方式或联系客服。'}}</text><button v-else class="ui-button primary full" :loading="busy" @click="pay">{{cashierPaymentText.confirm}}</button></view></template>
   <template v-if="screen==='pay-success'"><view class="success-state"><view class="success-icon">✓</view><text class="product-title">{{currentOrder?.payment_mode==='wechat'?(paymentParts(currentOrder)?'支付成功':'微信支付成功'):currentOrder?.payment_mode==='credit'?'账期采购已确认':currentOrder?.payment_mode==='bank_transfer'?'对公付款已确认':currentOrder?.payment_mode==='wallet'?'余额支付成功':currentOrder?.payment_mode==='rebate'?'企业返利抵扣成功':exchangeOrder(currentOrder)?'积分兑换成功':'订单记录已生成'}}</text><text class="money-xl">{{exchangeOrder(currentOrder)?(currentOrder.points_used?currentOrder.points_used+' 积分':'¥0.00'):'¥'+money(currentOrder?.amount)}}</text><text v-if="paymentPartsText(currentOrder)" class="small">{{paymentPartsText(currentOrder)}}</text><text class="muted small">{{currentOrder?.payment_mode==='wechat'?'微信已确认到账，订单已同步商家':currentOrder?.payment_mode==='credit'?'已确认账期采购，请按账单日期还款':currentOrder?.payment_mode==='bank_transfer'?'财务已核实对公到账，订单已同步后台':currentOrder?.payment_mode==='wallet'?'订单金额已从余额中扣除，可查看订单进度':currentOrder?.payment_mode==='rebate'?'订单金额已由企业返利抵扣，无需外部付款':currentOrder?.payment_mode==='simulation'?'当前为非实收记账，未发生真实扣款':exchangeOrder(currentOrder)?'积分已扣除，兑换的商品会按订单进度为您安排':'请查看订单记录确认付款状态和处理进度'}}</text><view class="success-actions"><button class="ui-button primary" @click="go('order-detail',{id:query.id})">查看订单</button><button class="ui-button outline" @click="channel==='B'?home('business'):home()">{{channel==='B'?'继续采购':'继续购物'}}</button></view></view><view class="section-title">为您推荐</view><view class="product-grid three"><view v-for="p in products.slice(0,6)" :key="p.id" class="product-card" @click="openProduct(p)"><image :lazy-load="true" :src="asset(p.image)" mode="aspectFit"/><text class="product-name">{{p.name}}</text><text class="price">¥{{money(unitPrice(p))}}</text><text v-if="soldCountText(p.soldCount)" class="sold-count">{{soldCountText(p.soldCount)}}</text></view></view></template>
   <template v-if="screen==='orders'"><view v-if="member?.enterprise_access" class="order-channel"><text :class="{active:channel==='C'}" @click="chooseOrderChannel('C')">商城订单</text><text :class="{active:channel==='B'}" @click="chooseOrderChannel('B')">采购订单</text></view><view v-if="channel==='C'" class="filter-bar"><text :class="{on:!orderBusiness&&!orderFilter}" @click="orderBusiness='';orderFilter=''">全部订单</text><text v-if="orderFilter" class="on" @click="orderFilter=''">{{labels[orderFilter]}} ✕</text><text :class="{on:orderBusiness==='retail'}" @click="orderBusiness='retail';orderFilter=''">零售</text><text :class="{on:orderBusiness==='partner'}" @click="orderBusiness='partner';orderFilter=''">专属拿货</text></view><view v-for="o in displayedOrders" :key="o.id" class="white-card order-card"><view class="between" @click="go('order-detail',{id:o.id})"><view><text class="small muted block">{{o.business_type==='partner'?'专属拿货 · '+(parse(o.rules_json).partner?.name||''):o.channel==='B'?'历史企业采购':'零售订单'}}</text></view><text class="price small">{{orderStatus(o)}}</text></view><view v-for="i in o.items" :key="i.id" class="checkout-item" @click="go('order-detail',{id:o.id})"><image :lazy-load="true" :src="asset(i.image)" mode="aspectFill"/><view><text class="bold">{{i.name}}</text><text class="small muted block">{{i.spec}}</text><text class="block">¥{{money(i.price)}}</text></view><text class="more small">×{{i.quantity}}</text></view><view class="order-total">共 {{o.items.reduce((a,i)=>a+i.quantity,0)}} 件商品　{{orderAmountLabel(o)}} <text class="price">¥{{money(o.amount)}}</text></view><view class="order-actions"><button class="ui-button outline" @click="go('order-detail',{id:o.id})">查看详情</button><button v-if="o.status==='pending'" class="ui-button primary" @click="this.go('cashier',{id:o.id})">去付款</button><button v-if="o.status==='shipped'" class="ui-button primary" @click="receive(o)">确认收货</button></view></view><view v-if="!displayedOrders.length" class="empty"><UiIcon name="bag" :size="60"/><text>暂无相关订单</text><button class="ui-button primary" @click="channel==='B'?go('business'):home()">去逛逛</button></view></template>
   <template v-if="screen==='order-detail'&&currentOrder"><OrderProgress :order-id="currentOrder.id" :status-title="orderStatus(currentOrder)" :status-hint="statusHint" :refresh-tick="refreshTick" @refresh="refresh(true)"/><view v-if="currentOrder.business_type==='partner'" class="notice">专属拿货 · {{parse(currentOrder.rules_json).partner?.name}} · 成交折扣{{parse(currentOrder.rules_json).partner?.rate/1000}}折。退款按原成交金额处理。</view><PurchaseDocument v-if="currentOrder.channel==='B'" :order-id="currentOrder.id"/><view v-if="currentOrder.tracking" class="white-card" @click="go('logistics',{id:currentOrder.id})"><view class="line"><UiIcon name="truck"/><text>{{currentOrder.carrier}}</text><text class="more">查看物流 ›</text></view><text class="small muted">{{currentOrder.tracking}}</text></view><view class="white-card"><text class="bold">{{parse(currentOrder.address_json).name}}　{{parse(currentOrder.address_json).phone}}</text><text class="small muted block">{{parse(currentOrder.address_json).address}}</text></view><view class="white-card"><view v-for="i in currentOrder.items" :key="i.id" class="checkout-item"><image :lazy-load="true" :src="asset(i.image)" mode="aspectFill"/><view><text>{{i.name}}</text><text class="small muted block">{{i.spec}}</text><text v-if="i.refunded_quantity" class="small muted block">已退 {{i.refunded_quantity}} 件 · 待发 {{i.remaining_to_ship}} 件</text><text>¥{{money(i.price)}}</text></view><text class="more">×{{i.quantity}}</text></view><view class="line"><text class="muted">商品金额</text><text class="more">¥{{money(currentOrder.subtotal)}}</text></view><view v-if="offerDiscount(currentOrder)" class="line"><text class="muted">优惠金额</text><text class="more price">−¥{{money(offerDiscount(currentOrder))}}</text></view><view v-if="Number(currentOrder.points_discount)>0" class="line"><text class="muted">{{parse(currentOrder.rules_json).exchange?'积分兑换':'积分抵扣'}}（{{currentOrder.points_used}}分）</text><text class="more price">−¥{{money(currentOrder.points_discount)}}</text></view><view v-if="shippingText(currentOrder.shipping_amount,currentOrder.delivery_method)" class="line"><text class="muted">运费</text><text class="more">{{shippingText(currentOrder.shipping_amount,currentOrder.delivery_method)}}</text></view><view v-if="currentOrder.payment_mode" class="line"><text>付款方式</text><text>{{paymentModeLabel(currentOrder)}}</text></view><template v-if="paymentParts(currentOrder)"><view class="line"><text>余额支付</text><text>¥{{money(currentOrder.wallet_amount)}}</text></view><view class="line"><text>微信支付</text><text>¥{{money(currentOrder.external_amount)}}</text></view></template><view v-if="currentOrder.rebate_amount" class="line"><text>{{currentOrder.status==='pending'?'企业返利已占用':'企业返利抵扣'}}</text><text>¥{{money(currentOrder.rebate_amount)}}</text></view><view class="line"><text>{{orderAmountLabel(currentOrder)}}</text><text class="more price">¥{{money(currentOrder.amount)}}</text></view><view v-if="currentOrder.refunded_amount" class="line"><text>已处理退款</text><text>¥{{money(currentOrder.refunded_amount)}}</text></view><text v-if="refundPartsText(currentOrder)" class="small muted block">{{refundPartsText(currentOrder)}}</text></view><view class="white-card"><view class="line"><text class="muted small">订单编号</text><text class="more small" @click="copy(currentOrder.order_no)">{{currentOrder.order_no}} ⧉</text></view><view class="line"><text class="muted small">下单时间</text><text class="more small">{{date(currentOrder.created_at)}}</text></view></view><view v-if="afterSaleAction(currentOrder).closed" class="notice">已超过售后申请期限（收货后 {{afterSaleWindowDays(currentOrder)}} 天内可直接申请），如需售后请联系客服协助处理。</view><view v-if="['pending','paid','shipping','shipped','completed','refunded'].includes(currentOrder.status)" class="bottom-bar order-bottom"><button v-if="currentOrder.status==='pending'" class="ui-button outline" @click="cancel(currentOrder)">取消订单</button><button v-if="currentOrder.status==='pending'" class="ui-button primary" @click="go('cashier',{id:currentOrder.id})">去付款</button><button v-if="['paid','shipping','shipped','completed','refunded'].includes(currentOrder.status)" class="ui-button outline" @click="go(afterSaleAction(currentOrder).page,{id:currentOrder.id})">{{afterSaleAction(currentOrder).label}}</button><button v-if="currentOrder.status==='shipped'" class="ui-button primary" @click="receive(currentOrder)">确认收货</button><button v-if="currentOrder.status==='completed'" class="ui-button primary" @click="go('reviews',{id:currentOrder.id,orderNo:currentOrder.order_no})">去评价</button><button v-if="['completed','refunded'].includes(currentOrder.status)" class="ui-button outline" @click="buyAgain(currentOrder)">再买一次</button></view></template>
   <template v-if="screen==='logistics'"><view v-for="(p,i) in parcels" :key="p.id" class="white-card"><text class="bold">第 {{i+1}} 批 · {{p.fully_refunded?'本批已退完，无需收货':p.received?'已确认收货':'已发货'}}</text><text class="description block" @click="copy(p.tracking)">{{p.carrier}} {{p.tracking}} ⧉</text><text v-for="item in parse(p.items_json)" :key="item.id" class="small block">{{item.name}} {{item.spec}} × {{item.quantity}}</text><button v-if="!p.received&&!p.fully_refunded" class="ui-button outline" @click="receiveParcel(p)">确认本批收货</button></view><view v-if="!parcels.length" class="white-card"><view class="section-title compact">{{currentOrder?.carrier||'暂未发货'}}</view><text @click="copy(currentOrder?.tracking)" class="muted">运单号：{{currentOrder?.tracking||'暂无'}} ⧉</text></view><view class="white-card"><view class="timeline-dot">●</view><text class="bold">{{currentOrder?.status==='completed'?'已确认收货':['shipping','shipped'].includes(currentOrder?.status)?'商家已发货':currentOrder?.tracking?'订单已结束':'暂未发货'}}</text><text class="muted block small">运单由后台填写，当前尚未接入实时物流轨迹。</text></view></template>
   <view v-if="reasonPickerOpen" class="overlay" @click="reasonPickerOpen=false"><view class="sheet reason-sheet" @click.stop><text class="product-title">选择售后原因</text><button class="ui-button" v-for="option in [{key:'customer',name:'个人原因'},{key:'merchant',name:'商品或商家原因'}]" :key="option.key" :class="{chosen:reasonCode===option.key}" @click="reasonCode=option.key;refundShipping=false;reasonPickerOpen=false">{{option.name}}<text v-if="reasonCode===option.key"> ✓</text></button><button class="ui-button outline" @click="reasonPickerOpen=false">取消</button></view></view><template v-if="screen==='after-sale'"><view class="white-card"><text class="product-title">选择售后商品</text><text class="small muted block case-guidance">勾选需要售后的商品，系统自动处理该商品当前全部可申请部分，无需填写数量。</text><view v-for="i in currentOrder?.items" :key="i.id" class="case-item" :class="{'case-selected':!!caseQuantities[i.id],'case-unavailable':!caseMaximum(i)}" @click="toggleCaseItem(i)"><view class="check" :class="{checked:!!caseQuantities[i.id]}">{{caseQuantities[i.id]?'✓':''}}</view><image :src="asset(i.image)" mode="aspectFit"/><view class="case-item-info"><text class="bold block">{{i.name}}</text><text class="small muted block">{{i.spec}}</text><text class="small block">{{!caseMaximum(i)?'当前不可申请售后':caseQuantities[i.id]?'已选择 · 按可售后范围申请':'点击选择此商品'}}</text></view></view><view class="filter-chips"><text v-for="(label,key) in caseTypes" :key="key" :class="{selected:caseType===key}" @click="chooseCaseType(key)">{{label}}</text></view><view class="line"><text>售后原因</text><text class="more" @click="reasonPickerOpen=true">{{reasonCode==='merchant'?'商品或商家原因':'个人原因'}} ›</text></view><view v-if="reasonCode==='merchant'&&['refund','return'].includes(caseType)&&currentOrder?.shipping_amount" class="line"><text>整单申请退原运费</text><switch :checked="refundShipping" @change="refundShipping=$event.detail.value"/></view><text v-if="reasonCode!=='merchant'&&['refund','return'].includes(caseType)&&currentOrder?.shipping_amount" class="small muted block">按个人原因退款不退运费 ¥{{money(currentOrder.shipping_amount)}}；如果是商品或商家的问题，请把售后原因选为“商品或商家原因”。</text><view class="line"><text>图片凭证（最多3张，选填）</text><button class="ui-button outline mini" :disabled="caseProofs.length>=3" @click="chooseCaseProof">上传图片</button></view><view v-for="(proof,i) in caseProofs" :key="proof" class="line"><image class="proof-preview" :src="caseProofPreviews[proof]" mode="aspectFill" @click="previewCaseProof(proof)"/><text @click="caseProofs.splice(i,1)">移除</text></view><textarea class="field textarea" v-model="reason" placeholder="请说明原因" maxlength="500"/></view><view class="bottom-bar"><button class="ui-button primary full" :loading="busy" @click="submitCase">提交申请</button></view></template>
   <template v-if="screen==='after-sales'"><view class="after-sales-heading"><text>售后处理进度</text><button class="ui-button outline mini" @click="refresh(true)">刷新状态</button></view><view v-for="c in cases" :key="'case'+c.id" class="white-card after-sale-record"><view class="between case-title"><text class="bold">{{caseLabel(c)}}</text><text class="price">{{['refund','return'].includes(c.type)?'¥'+money(c.amount):'换货 / 补发'}}</text></view><text v-if="caseRefundText(c)" class="small block">{{caseRefundText(c)}}</text><text class="small block">订单 {{c.order_no}}</text><text v-for="i in parse(c.items_json)" :key="i.id" class="small block">{{i.name}} {{i.spec}} × {{i.quantity}}{{i.parentCaseId?' · 关联上次售后 #'+i.parentCaseId:''}}</text><text v-if="['refund','return'].includes(c.type)" class="small muted block">{{c.status==='refunded'?'退款金额':'申请退款金额'}}按所选商品优惠后的实付款分摊，精确到分；待审核不代表已到账。</text><text class="description block">{{c.reason}}</text><text class="description block">{{c.note}}</text><CaseProofs v-if="caseProofCount(c)" :case-id="c.id" :count="caseProofCount(c)"/><view v-if="c.status==='awaiting_return'&&c.return_due_at" class="small muted">请于 {{date(c.return_due_at)}} 前填写寄回运单；超期请联系客服延长。寄回运费由{{c.return_shipping_payer==='merchant'?'商家':'买家'}}承担。</view><text v-if="c.status==='awaiting_return'&&c.return_address" class="description block">寄回地址：{{c.return_address}}</text><text v-if="c.status==='rejected'&&c.return_due_at" class="small muted block">这次售后已关闭，请不要再寄回商品；{{reapplyClosed(c)?'如仍需退货，请联系客服协助处理。':'如仍需退货，请点击下方重新申请。'}}</text><template v-if="c.status==='awaiting_return'"><input class="field" v-model="returnForms[c.id].carrier" placeholder="寄回物流公司"/><input class="field" v-model="returnForms[c.id].tracking" placeholder="寄回运单号"/><button class="ui-button primary" @click="sendReturn(c)">提交寄回运单</button></template><text v-if="c.return_tracking" class="small block">寄回：{{c.return_carrier}} {{c.return_tracking}}</text><text v-if="c.replacement_tracking" class="small block">换补发：{{c.replacement_carrier}} {{c.replacement_tracking}}</text><button v-if="c.status==='reshipped'" class="ui-button primary" @click="receiveReplacement(c)">确认换补发收货</button><template v-if="c.status==='rejected'"><button v-if="!reapplyClosed(c)" class="ui-button outline" @click="go('after-sale',{id:c.order_id})">修改并重新申请</button><template v-else><text class="small muted block">已超过售后申请期限，如需售后请联系客服协助处理。</text><button class="ui-button outline" @click="go('support')">联系客服</button></template></template><button class="ui-button outline" @click="go('order-detail',{id:c.order_id})">查看关联订单</button></view><view v-for="a in afterSales" :key="a.id" class="white-card"><view class="between"><text class="bold">{{a.status==='pending'?'商家处理中':a.status==='refunded'?'退款已完成':'申请已驳回'}}</text><text class="price">¥{{money(a.amount)}}</text></view><text class="small muted block">订单 {{a.order_no}}</text><text class="block description">申请原因：{{a.reason}}</text><text v-if="a.note" class="block description">处理说明：{{a.note}}</text><text v-if="a.status==='rejected'&&reapplyClosed(a)" class="small muted block">已超过售后申请期限，如需售后请联系客服协助处理。</text><view class="order-actions"><button class="ui-button outline" @click="go('order-detail',{id:a.order_id})">查看订单</button><template v-if="a.status==='rejected'"><button v-if="!reapplyClosed(a)" class="ui-button primary" @click="go('after-sale',{id:a.order_id})">修改并重新申请</button><button v-else class="ui-button primary" @click="go('support')">联系客服</button></template></view><text class="small muted block">{{a.status==='pending'?'商家审核后，处理结果会显示在这里。':demoMode?'当前为测试售后，不发生真实退款。':'处理结果请查看售后详情，并核对原支付渠道的到账记录。'}}</text></view><view v-if="!afterSales.length&&!cases.length" class="empty"><UiIcon name="refund" :size="52"/><text>暂无售后申请</text></view></template>
