 afterLogin(data){const previous=uni.getStorageSync('shop-owner');claimGuestCart(data.member.id);if(loginReferrer())clearReferral();uni.setStorageSync('shop-owner',data.member.id);if(previous&&String(previous)!==String(data.member.id))uni.removeStorageSync('shop-return');uni.setStorageSync('shop-token',data.token);uni.setStorageSync('shop-member',data.member);uni.removeStorageSync('shop-selected-address');/* 新注册或还没留姓名手机号的，先去完善资料，完成后再回原来要去的页面 */if(memberNeedsProfile(data.member)){uni.redirectTo({url:'/pages/settings/index?complete=1'});return}this.continueAfterLogin()},continueAfterLogin(){const target=uni.getStorageSync('shop-return');uni.removeStorageSync('shop-return');if(target){uni.redirectTo({url:'/pages/'+target.screen+'/index?'+Object.keys(target.query||{}).map(k=>k+'='+encodeURIComponent(target.query[k])).join('&')})}else home('me')},async getQuote(){const sequence=++this.quoteSequence;this.quoteLoading=true;this.quoteError='';try{if(!this.checkoutItems.length)throw Error('请先选择商品');if(this.checkoutItems.some(i=>i.invalid))throw Error('请确认并移除失效商品后继续');const result=await request('/quote','POST',{address:this.checkoutAddress(),channel:this.channel,purchaseMode:this.partnerPurchase?'partner':'standard',exchange:this.exchange,campaignId:this.campaignId,groupId:this.groupId,bundles:this.bundles,deliveryMethod:this.deliveryMethod,pickupPoint:this.pickupPoint,paymentMethod:this.paymentMethod,items:this.checkoutItems.map(i=>({id:i.id,quantity:i.quantity})),coupon:this.useCoupon,couponId:this.channel==='C'?this.couponId:0,useRebate:this.useRebate,expectedRebate:this.quote.rebateUsed||0,useOnlineBalance:this.useOnlineBalance&&this.channel==='C'&&!this.partnerPurchase,useBalance:this.useBalance&&this.rules.walletPaymentEnabled!==false,expectedWallet:this.quote.walletUsed||0,usePoints:this.usePoints,expectedPoints:this.quote.pointsUsed||0});if(sequence===this.quoteSequence)this.quote=result}catch(e){if(sequence===this.quoteSequence){this.quoteError=e.message;notify(e)}}finally{if(sequence===this.quoteSequence)this.quoteLoading=false}},restorePendingSubmission(){
 const owner=getToken()&&uni.getStorageSync('shop-owner');
 const state=owner?uni.getStorageSync(this.cartKey('checkout'))||{}:{};
 const pending=owner?uni.getStorageSync('shop-pending-order-'+owner)||state.pendingSubmission||null:null;
 this.pendingSubmission=pending;
 if(owner&&pending)uni.setStorageSync('shop-pending-order-'+owner,pending);
 return pending;
},
setPendingSubmission(payload){
 const owner=getToken()&&uni.getStorageSync('shop-owner');
 if(!owner)return;
 const previous=this.pendingSubmission;
 if(payload)uni.setStorageSync('shop-pending-order-'+owner,payload);else uni.removeStorageSync('shop-pending-order-'+owner);
 this.pendingSubmission=payload;
 const key=this.cartKey('checkout'),state=uni.getStorageSync(key)||{};
 if(payload&&state.requestKey===payload.requestKey){state.pendingSubmission=payload;uni.setStorageSync(key,state)}
 else if(!payload&&state.pendingSubmission?.requestKey===previous?.requestKey){delete state.pendingSubmission;uni.setStorageSync(key,state)}
},
submitOrder(){return this.run(async()=>{
 const submissionToken=getToken(),submissionOwner=uni.getStorageSync('shop-owner');
 if(!submissionToken||!submissionOwner||(this.member&&String(this.member.id)!==String(submissionOwner)))throw Error('登录状态已变更，请刷新后重试');
