 }
 const payload=JSON.parse(JSON.stringify(this.pendingSubmission||{channel:this.channel,checkoutSource:this.checkoutSource,cartRevision:this.checkoutSource==='cart'?this.checkoutCartRevision:undefined,purchaseMode:this.partnerPurchase?'partner':'standard',exchange:this.exchange,campaignId:this.campaignId,groupId:this.groupId,bundles:this.bundles,deliveryMethod:this.deliveryMethod,pickupPoint:this.pickupPoint,paymentMethod:this.paymentMethod,items:this.checkoutItems.map(i=>({id:i.id,quantity:i.quantity})),coupon:this.useCoupon,couponId:this.channel==='C'?this.couponId:0,useRebate:this.useRebate,expectedRebate:this.quote.rebateUsed||0,useOnlineBalance:this.useOnlineBalance&&this.channel==='C'&&!this.partnerPurchase,useBalance:this.useBalance&&this.rules.walletPaymentEnabled!==false,expectedWallet:this.quote.walletUsed||0,usePoints:this.usePoints,expectedPoints:this.quote.pointsUsed||0,address:this.checkoutAddress(),expectedAmount:this.quote.amount,requestKey:this.requestKey}));
 if(recovering&&!await this.confirm('上次提交结果尚未确认。将按原提交内容核对或重试，之后修改的地址和商品不会应用到原订单。原收货人：'+payload.address.name+' '+payload.address.phone+'，'+payload.address.address+'；原金额 ¥'+money(payload.expectedAmount)+'。是否继续核对？'))return;
 if(submissionToken!==getToken()||String(submissionOwner)!==String(uni.getStorageSync('shop-owner')))throw Object.assign(Error('登录状态已变更'),{staleSession:true});
 this.member=await ensureReferralBeforeOrder(this.member);
 this.setPendingSubmission(payload);
 let o;
 try{o=await request('/orders','POST',payload)}catch(e){
  if(!e.staleSession&&!e.uncertain&&submissionToken===getToken())this.setPendingSubmission(null);
  if(/价格已更新/.test(e.message)&&!e.uncertain){const old=payload.expectedAmount;await this.refresh();if(this.quote.items)await this.confirm('价格已更新：原金额 ¥'+money(old)+'，现为 ¥'+money(this.quote.amount)+'。请核对后再次点击提交订单。');return;}
  throw e;
 }
 this.setPendingSubmission(null);
 if(o.approvalRequired){go('company');return;}
 if(payload.purchaseMode==='partner')uni.removeStorageSync('shop-partner-list-'+uni.getStorageSync('shop-owner'));
 if(o.cart){this.cart=o.cart.items;this.cartRevision=o.cart.revision;uni.setStorageSync(this.cartKey(payload.channel),this.cart)}
 const actual=this.parse(o.address_json),address=payload.address;
