 if(recovering||changed){notify('订单已确认，请核对收货信息和金额后再付款');go('order-detail',{id:o.id,channel:o.channel||payload.channel});return;}
 go('cashier',{id:o.id});
})},chooseAddress(a){uni.setStorageSync('shop-selected-address',a);if(this.query.select)this.back();else uni.showToast({title:'已选择地址',icon:'success'})},saveAddress(){this.run(async()=>{if(['province','city','district','detail'].some(k=>!this.addressForm[k]?.trim()))throw Error('请填写省、市、区县及详细地址');if(!/^1[3-9][0-9]{9}$/.test(String(this.addressForm.phone||'')))throw Error('请填写正确的11位手机号');await request('/addresses','POST',this.addressForm);this.clearDraft();this.addressForm={};this.back()})},deleteAddress(a){this.run(async()=>{if(!await this.confirm('确认删除这个收货地址？'))return;await request('/addresses/'+a.id,'DELETE');await this.refresh()})},paymentSuccess(){const url='/pages/pay-success/index?id='+encodeURIComponent(this.query.id)+'&channel='+this.channel;return new Promise((resolve,reject)=>uni.redirectTo({url,success:resolve,fail:()=>uni.reLaunch({url,success:resolve,fail:()=>reject(Error('付款已成功，页面跳转失败，请从订单列表查看订单'))})}))},pay(){return this.run(async()=>{if(this.wechatPayReady&&!this.currentOrder?.credit_order&&Number(this.currentOrder?.external_amount)>0){if(!this.isWechat)throw Error(h5ActionText(this.rules.shopName,'付款'));await payWithWechat(this.query.id)}else await request('/orders/'+this.query.id+'/pay','POST',{});await this.paymentSuccess()})},confirm(content){this.resolveConfirm(false);this.confirmation=content;return new Promise(resolve=>{this._confirmResolve=resolve})},resolveConfirm(value){const resolve=this._confirmResolve;this._confirmResolve=null;this.confirmation='';if(resolve)resolve(value)},receive(o){this.run(async()=>{if(!await this.confirm('请确认商品已收到且无误。'))return;await request('/orders/'+o.id+'/receive','POST',{});await this.refresh()})},cancel(o){this.run(async()=>{if(!await this.confirm('确认取消这笔未付款订单？'))return;const result=await request('/orders/'+o.id+'/cancel','POST',{});if(result?.paid)uni.showModal({title:'订单已付款',content:'这笔订单已经付款成功，不用再取消，商家会尽快处理。',showCancel:false});await this.refresh()})},retailListPrice(p){const v=Number(p&&p.standardPrice);return p&&p.standardPrice!=null&&Number.isFinite(v)?v:this.unitPrice(p)},campaignOffer(p){return this.channel==='C'?offerFor(this.campaignOffers,p,this.unitPrice(p)):null},promoteOffer(p){return this.channel==='C'?offerFor(this.campaignOffers,p,this.retailListPrice(p)):null},afterSaleAction(o){const c=this.currentAfterSale;if(this.activeCase||o.status==='refunded'||(c&&c.status!=='rejected'))return {label:'售后进度',page:'after-sales'};if(afterSaleClosed(o,serverNow()))return {label:'联系客服',page:'support',closed:true};return {label:c?'重新申请':'申请售后',page:'after-sale'}},afterSaleWindowDays(o){return afterSaleDays(o)},reapplyClosed(row){/* 新后端随售后记录带上订单收货信息；旧后端没有时用读到的订单，读不到按未过期处理（由服务器把关） */const o=row&&('order_received_at' in row)?{received_at:row.order_received_at,rules_json:row.order_rules_json,manual_after_sale_until:row.order_manual_after_sale_until}:(this.orders||[]).find(x=>String(x.id)===String(row&&row.order_id));return !!o&&afterSaleClosed(o,serverNow())},shippingText,againPriceText(i){const q=this.quote.items?.find(x=>x.id===i.id);if(q&&q.unitPrice!=null)return '现单价 ¥'+money(q.unitPrice);return this.products.some(p=>p.id===i.id)?'现单价 ¥'+money(this.unitPrice(i)):'该商品已下架或暂不可售'},buyAgain(o){if(o.business_type==='partner'||o.channel==='B'){go('partner');return;}this.channel=o.channel;/* 赠品（0 元行）不带进结算：活动中会卡住结算，活动结束后会按原价收钱（复核 FC-11） */const items=(o.items||[]).filter(i=>Number(i.price)>0);if(!items.length){notify('这笔订单没有可以再次购买的商品（赠品不能单独购买）');return;}this.startCheckout(items.map(i=>({id:i.product_id,name:i.name,spec:i.spec,image:i.image,quantity:i.quantity,previousPrice:i.price})))},submitAfterSale(){this.run(async()=>{await request('/after-sales','POST',{orderId:Number(this.query.id),reason:this.reason});uni.redirectTo({url:'/pages/after-sales/index?channel='+this.channel})})},previewLicense(){if(this.licensePreview)uni.previewImage({current:this.licensePreview,urls:[this.licensePreview],fail:()=>notify('图片预览失败，请重新选择 JPG 或 PNG 图片')})},
 selectLicenseFile(path,size){
  if(!path){notify('未取得图片，请重新选择');return}
  this.licenseLocalPath=path;this.licensePreview=path;this.licenseImageError=false;this.licenseImageFallback=false;
  this.application={...this.application,license:''};this.licenseError='';this.applicationError='';this.saveDraft();
    return this.uploadSelectedLicense()
 },
 uploadSelectedLicense(){
  if(!this.licenseLocalPath||this.busy)return;
  const path=this.licenseLocalPath;
  this.licenseStatus='uploading';this.licenseError='';
  return this.run(async()=>{try{
   const uploaded=await uploadLicense(path);
   this.application={...this.application,license:uploaded};this.licenseStatus='uploaded';this.saveDraft();
   uni.showToast({title:'上传成功',icon:'success'})
  }catch(e){this.licenseStatus='failed';this.licenseError=e.message||'上传失败，请重试';throw e}})
 },
 onLicensePreviewError(){
