 uni.chooseImage({count:1,sizeType:['compressed'],success:r=>selected(r.tempFilePaths?.[0],r.tempFiles?.[0]?.size),fail:failed});
 // #endif
 },submitApplication(){if(this.busy||this.licenseStatus==='uploading')return;if((this.screen==='enterprise-apply'||this.distributionApplication.required)&&!this.application.license){this.applicationError='图片尚未上传成功，请先完成上传';return;}const a=this.application,name=String(a.name||'').trim(),phone=String(a.phone||'').trim();this.applicationError=!name?'请输入真实姓名':name.length<2||name.length>60?'姓名请填写2至60个字':!phone?'请输入联系手机号':!/^1[3-9][0-9]{9}$/.test(phone)?'请输入正确的11位手机号':!a.agreed?'请先阅读并勾选入驻协议与隐私说明':'';if(this.applicationError)return;this.application={...a,name,phone};this.run(async()=>{const enterprise=this.screen==='enterprise-apply';await request('/applications/'+(enterprise?'enterprise':'distributor'),'POST',{...this.application,inviterId:enterprise?0:Number(this.query.referrer||0)});this.clearDraft();this.application={};uni.redirectTo({url:'/pages/'+(enterprise?'business':'distribution')+'/index'})})},shareInvite(){if(this.member?.distributor_state!=='approved')return notify('请先通过分销审核');this.copy((this.rules.shareBaseUrl||'https://luoluo.oksja.cn')+'/#/pages/distributor-apply/index?referrer='+this.member.id)},shareProduct(p){try{return this.copy(buildProductLink({id:p?.id,channel:this.channel,member:this.member,baseUrl:this.rules.shareBaseUrl||'https://luoluo.oksja.cn'}))}catch(e){notify(e)}},logout(){return this.run(async()=>{const revoke=request('/logout','POST',{}).catch(()=>{});this.suspend();clearLocalSession();this.member=null;home('me');await revoke})}
 }
}
