.order-bottom{justify-content:flex-end!important}.order-bottom>button{max-width:none;flex:1}.reason-sheet button{width:100%;margin-top:12px;background:var(--shop-background, #f3f8fb);color:var(--shop-ink, #28546c)}.reason-sheet button.chosen{background:var(--shop-soft, #eaf5fb);font-weight:600}.screen .order-status{padding:22px 24px}.screen .order-status .product-title{font-size:23px}.screen .order-status .small{margin-top:8px}.screen .success-state{padding:30px 20px}.screen .success-state .success-icon{width:64px;height:64px;line-height:64px;font-size:40px;margin-bottom:16px}.screen .success-state .money-xl{font-size:36px;margin:16px 0}.screen .application-hero{height:160px}.screen .order-card .checkout-item{padding:14px 0}

